package com.dentalcare.api.modules.contactinquiries.controller;
import com.dentalcare.api.modules.contactinquiries.dto.request.UpdateContactInquiryStatusRequest;
import com.dentalcare.api.modules.contactinquiries.dto.response.ContactInquiryResponse;
import com.dentalcare.api.modules.contactinquiries.model.ContactInquiryStatus;
import com.dentalcare.api.modules.contactinquiries.service.ContactInquiryService;
import com.dentalcare.api.security.service.AuthenticatedUser;
import jakarta.validation.Valid; import org.springframework.data.domain.Page; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/api/v1/contact-inquiries") @PreAuthorize("hasRole('ADMINISTRATOR')") public class ContactInquiryController { private final ContactInquiryService service; public ContactInquiryController(ContactInquiryService service){this.service=service;} @GetMapping public ResponseEntity<Page<ContactInquiryResponse>> findAll(@RequestParam(required=false) ContactInquiryStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ResponseEntity.ok(service.findAll(status,page,size));} @GetMapping("/{id}") public ResponseEntity<ContactInquiryResponse> findById(@PathVariable UUID id){return ResponseEntity.ok(service.findById(id));} @PatchMapping("/{id}/status") public ResponseEntity<ContactInquiryResponse> updateStatus(@PathVariable UUID id,@Valid @RequestBody UpdateContactInquiryStatusRequest request,@AuthenticationPrincipal AuthenticatedUser principal){return ResponseEntity.ok(service.updateStatus(id,request,principal.userId()));} }
